#!/bin/bash
# Rebuild v3, step 1: purge the by_seq esmc_300m content-addressed cache (it
# was built with the BOS/EOS-not-stripped bug in ESMCBackend.get_sequence_embeddings
# -- every cached embedding was (L+2, D) instead of (L, D), silently shifting
# every downstream training run and attribution by one position) and warm it
# fresh with the FIXED adapter (src/igloo/esm_adapter.py, fixed 2026-09-15).
#
# onehot-input results are UNAFFECTED by this bug (they never touch ESM-C) and
# are NOT regenerated by this rebuild.

#SBATCH --account=rrg-mahadeva_gpu
#SBATCH --job-name=rebuild_warm_v3
#SBATCH --output=jobs/logs/rebuild_warm_v3_%j.out
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=4
#SBATCH --mem=128G
#SBATCH --time=4:00:00

cd /project/6007171/ranaab/IGLOO || exit 1
module load python/3.12 cuda/12.2
source IGLOO_env/bin/activate

echo "=== purging the buggy esmc_300m by_seq cache ==="
BEFORE=$(find data/embeddings/by_seq/esmc_300m -name '*.safetensors' 2>/dev/null | wc -l)
rm -rf data/embeddings/by_seq/esmc_300m
echo "removed $BEFORE stale (BOS/EOS-shifted) embedding files"

# also clear any leftover legacy batched caches for GB1/T4 in case anything survived
rm -f data/embeddings/synthetic/GB1_*_integrated_gradients_*.safetensors
rm -f data/embeddings/synthetic/T4Lysozyme_*_integrated_gradients_*.safetensors
rm -f data/embeddings/synthetic/GB1_*_sample_*.safetensors
rm -f data/embeddings/synthetic/T4Lysozyme_*_sample_*.safetensors
rm -f data/embeddings/synthetic/sequence_ig_seq_*.safetensors
rm -f data/embeddings/synthetic/sequence_ig_baseline_*.safetensors
rm -f data/embeddings/sequence_ig_seq_*.safetensors
rm -f data/embeddings/sequence_ig_baseline_*.safetensors
rm -f data/embeddings/ism_GB1_*.safetensors data/embeddings/ism_T4Lysozyme_*.safetensors

python - <<'PY'
import pandas as pd
from src.igloo.embedding import get_embeddings

WT = {
 'GB1': 'MTYKLILNGKTLKGETTTEAVDAATAEKVFKQYANDNGVDGEWTYDDATKTFTVTE',
 'T4Lysozyme': ('MNIFEMLRIDEGLRLKIYKDTEGYYHIGIGHLLTKSPSLNAAKSELDKAIGRNCNGVITKDEAEKLFN'
                'QDVDAAVRGILRNAKLKPVYDSLDAVRRCALINMVFQMGETGVAGFTNSLRMLQQKRWDEAAVNLAKS'
                'RWYNQTPNRAKRVITTFRTGTWDAYKNL'),
}
AA = 'ACDEFGHIKLMNPQRSTVWY'
for P, wt in WT.items():
    seqs = set()
    for landscape in ('additive', 'epistatic', 'nonlinear'):
        seqs |= set(pd.read_csv(f'data/synthetic/{P}_{landscape}.csv')['SEQ'])
    seqs |= {wt[:i] + m + wt[i+1:] for i in range(len(wt)) for m in AA if m != wt[i]}
    seqs.add(wt)
    seqs = sorted(seqs)
    print(f'{P}: warming {len(seqs)} unique sequences (float32, BOS/EOS-fixed) ...', flush=True)
    get_embeddings(seqs, layer=33, batch_size=64, esm_model_name='esmc_300m')
    print(f'{P}: done', flush=True)
PY

echo "=== by_seq store (should be ~L=true residue count, spot check) ==="
find data/embeddings/by_seq -name '*.safetensors' | wc -l
python - <<'PY'
import hashlib
from pathlib import Path
from safetensors.torch import load_file
wt = 'MTYKLILNGKTLKGETTTEAVDAATAEKVFKQYANDNGVDGEWTYDDATKTFTVTE'
h = hashlib.sha1(wt.encode()).hexdigest()
p = Path('data/embeddings/by_seq/esmc_300m/L33') / h[:2] / f'{h}.safetensors'
t = load_file(str(p))
print("GB1 WT cached shape:", t['embedding'].shape, " expected L =", len(wt))
assert t['embedding'].shape[1] == len(wt), "STILL WRONG -- do not proceed with the rebuild"
print("OK -- shape matches true residue count")
PY
